INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'e5529b74-84c4-5693-b51b-f2632d041426', 'f267b4d6-a22e-59fa-9f2e-4474ace519e4',
  '**E3(L.O.4.2).** Hãy mô tả ngắn gọn TỐI THIỂU 3 giải pháp để cải thiện độ hiệu quả của giải thuật Quicksort mô tả như bên dưới (5 điểm)

```c
int divide(int* a, int lo, int hi)
{
    int pivot = a[hi];
    int i = lo;
    for (int j = lo; j < hi; j++) {
        if (a[j] < pivot) {
            swap(a[j], a[i]);
            i++;
        }
    }
    swap(a[i], a[hi]);
    return i;
}

void quickSort(int* a, int lo, int hi)
{
    if (low < high) {
        int p = divide(a, lo, hi);
        quickSort(a, lo, p - 1);
        quickSort(a, p + 1, hi);
    }
}
```

Đáp án: i = lo - 1', 15
);

