INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'c4883774-1f48-51cb-9d2f-af728bd15ddb', 'f267b4d6-a22e-59fa-9f2e-4474ace519e4',
  'G2(L.O.2.1). Cho biết giải thuật duyệt theo chiều sâu (DFS) như bên dưới (bên trái) và thứ tự các hàm được gọi khi chạy giải thuật duyệt theo chiều sâu trên một đồ thị có hướng (bên phải). Hãy vẽ lại đồ thị có hướng này. (10 điểm)

```cpp
void dfs(int v) {
    marked[v] = true;
    cout << v << \" \";
    for (int w : adj(v)) {
        if (!isMark(w))
            dfs(w);
    }
}

bool isMark(int v) {
    return marked[v];
}
```

dfs(1)
$\rightarrow$ isMark(3)
$\rightarrow$ dfs(3)
$\rightarrow$ isMark(2)
$\rightarrow$ dfs(2)
$\rightarrow$ isMark(4)
$\rightarrow$ dfs(4)
$\rightarrow$ isMark(5)
$\rightarrow$ dfs(5)
$\rightarrow$ isMark(4)
$\rightarrow$ isMark(5)
$\rightarrow$ isMark(2)

**Trả lời**

